const dScore=d=>{const v=dVerdict(d);return (PICK[(d.raw||{}).pick]||0)+(v?(v.c=="#16A34A"?2:v.c=="#B45309"?1:0):.5)*1000+(v&&v.conf==tx("High confidence","ثقة عالية")?500:0)+(d.pct||0)};
